// CreateTableWithDBType creates the Item_Ledger_Entry table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *ItemLedgerEntry) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, ItemLedgerEntryTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetItemLedgerEntryPostgresTableSchema()
	} else {
		schema = GetItemLedgerEntryTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Item_Ledger_Entry table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *ItemLedgerEntry) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, ItemLedgerEntryTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_no)`,
		fmt.Sprintf("%s$Item_Ledger_Entry$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (item_no, variant_code, drop_shipment, location_code, posting_date)`,
		fmt.Sprintf("%s$Item_Ledger_Entry$item_location", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index item_location: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_type, item_no, variant_code, drop_shipment, location_code, posting_date)`,
		fmt.Sprintf("%s$Item_Ledger_Entry$entry_type_item", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index entry_type_item: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_type, item_no, variant_code, source_type, source_no, posting_date)`,
		fmt.Sprintf("%s$Item_Ledger_Entry$entry_type_source", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index entry_type_source: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (source_type, source_no, entry_type, item_no, variant_code, posting_date)`,
		fmt.Sprintf("%s$Item_Ledger_Entry$source", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index source: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (item_no, variant_code, open, positive, location_code, posting_date)`,
		fmt.Sprintf("%s$Item_Ledger_Entry$item_open", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index item_open: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (closed_by_entry_no)`,
		fmt.Sprintf("%s$Item_Ledger_Entry$closed_by", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index closed_by: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_no, posting_date)`,
		fmt.Sprintf("%s$Item_Ledger_Entry$document", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index document: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (item_no, lot_no, serial_no)`,
		fmt.Sprintf("%s$Item_Ledger_Entry$lot_serial", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index lot_serial: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (cost_is_adjusted, item_no, adjust_invoice_cost)`,
		fmt.Sprintf("%s$Item_Ledger_Entry$cost_adjust", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index cost_adjust: %w", err)
	}
	var keys []sift.Key
	for _, spec := range itemLedgerEntrySIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, ItemLedgerEntryTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, ItemLedgerEntryTableName, keys)
}

// itemLedgerEntrySIFTSpecs are the table's keys with sum_index_fields
func itemLedgerEntrySIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{
		{
			Name:   "item_location",
			Fields: []sift.Column{{Name: "item_no", Kind: sift.KindText}, {Name: "variant_code", Kind: sift.KindText}, {Name: "drop_shipment", Kind: sift.KindBool}, {Name: "location_code", Kind: sift.KindText}, {Name: "posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "quantity", Kind: sift.KindDecimal}, {Name: "invoiced_quantity", Kind: sift.KindDecimal}, {Name: "remaining_quantity", Kind: sift.KindDecimal}},
		},
		{
			Name:   "entry_type_item",
			Fields: []sift.Column{{Name: "entry_type", Kind: sift.KindInt}, {Name: "item_no", Kind: sift.KindText}, {Name: "variant_code", Kind: sift.KindText}, {Name: "drop_shipment", Kind: sift.KindBool}, {Name: "location_code", Kind: sift.KindText}, {Name: "posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "invoiced_quantity", Kind: sift.KindDecimal}, {Name: "amount", Kind: sift.KindDecimal}, {Name: "adjusted_cost_invoiced_qty", Kind: sift.KindDecimal}},
		},
	}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *ItemLedgerEntry) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, ItemLedgerEntryTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range itemLedgerEntrySIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, ItemLedgerEntryTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: ItemLedgerEntryTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, ItemLedgerEntryTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

