// CopyFilters copies filters from another record variable (all filter groups)
func (t *ItemLedgerEntry) CopyFilters(from *ItemLedgerEntry) {
	t.filters = copyItemLedgerEntryFilters(from.filters)
	t.filterGroup = from.filterGroup
	t.otherFilters = nil
	for g, filters := range from.otherFilters {
		if t.otherFilters == nil {
			t.otherFilters = map[int]map[string]*itemLedgerEntryFilterCondition{}
		}
		t.otherFilters[g] = copyItemLedgerEntryFilters(filters)
	}

	// Also copy order by fields
	if len(from.orderByFields) > 0 {
		t.orderByFields = make([]string, len(from.orderByFields))
		copy(t.orderByFields, from.orderByFields)
	} else {
		t.orderByFields = nil
	}
}

// copyItemLedgerEntryFilters returns a deep copy of a filter group's filters (nil for none)
func copyItemLedgerEntryFilters(from map[string]*itemLedgerEntryFilterCondition) map[string]*itemLedgerEntryFilterCondition {
	if from == nil {
		return nil
	}
	filters := make(map[string]*itemLedgerEntryFilterCondition, len(from))
	for key, filter := range from {
		c := *filter
		filters[key] = &c
	}
	return filters
}

